import {describe, it, expect} from 'vitest';
import * as THREE from 'three';
import {buildPodium, podiumHeights} from '../src/podium.js';

describe('podium', () => {
  it('has three named steps', () => {
    const p = buildPodium({first: 3, second: 2, third: 1.2});
    expect(p.getObjectByName('step-1')).toBeTruthy();
    expect(p.getObjectByName('step-2')).toBeTruthy();
    expect(p.getObjectByName('step-3')).toBeTruthy();
  });

  it('orders heights 2-1-3 left to right', () => {
    const p = buildPodium({first: 3, second: 2, third: 1.2});
    const xs = [2, 1, 3].map(n => p.getObjectByName('step-' + n).position.x);
    expect(xs[0]).toBeLessThan(xs[1]);
    expect(xs[1]).toBeLessThan(xs[2]);
  });

  it('reports heights via Box3', () => {
    const p = buildPodium({first: 3, second: 2, third: 1.2});
    const h = podiumHeights(p);
    expect(h['step-1']).toBeCloseTo(3, 6);
    expect(h['step-3']).toBeCloseTo(1.2, 6);
  });

  it('rests every step on the ground', () => {
    const p = buildPodium({first: 3, second: 2, third: 1.2});
    p.updateMatrixWorld(true);
    for (const n of [1, 2, 3]) {
      const b = new THREE.Box3().setFromObject(p.getObjectByName('step-' + n));
      expect(b.min.y).toBeCloseTo(0, 6);
    }
  });
});

