import * as THREE from 'three';

const STEP_WIDTH = 2;
const STEP_DEPTH = 2;

/**
 * Build an Olympic-style winners' podium.
 *
 * Left-to-right ordering is second place, first place (centre), third place,
 * matching `step-2 < step-1 < step-3` on the x axis. Each step is a box whose
 * bottom face rests exactly on the ground plane y = 0.
 *
 * @param {{first: number, second: number, third: number}} heights
 * @returns {THREE.Group}
 */
export function buildPodium({first, second, third}) {
  const group = new THREE.Group();
  group.name = 'podium';

  const layout = [
    {name: 'step-2', height: second, x: -STEP_WIDTH},
    {name: 'step-1', height: first, x: 0},
    {name: 'step-3', height: third, x: STEP_WIDTH},
  ];

  for (const {name, height, x} of layout) {
    // BoxGeometry is centred on its origin, so lift each step by half its
    // height to keep its base at y = 0.
    const geometry = new THREE.BoxGeometry(STEP_WIDTH, height, STEP_DEPTH);
    const material = new THREE.MeshStandardMaterial();
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = name;
    mesh.position.set(x, height / 2, 0);
    group.add(mesh);
  }

  return group;
}

/**
 * Measure the world-space height of each named step using its bounding box.
 *
 * @param {THREE.Object3D} podium
 * @param {string[]} [names] step names to measure; defaults to step-1..step-3
 * @returns {Record<string, number>} bounding-box height per step
 */
export function podiumHeights(podium, names = ['step-1', 'step-2', 'step-3']) {
  const heights = {};
  for (const name of names) {
    const step = podium.getObjectByName(name);
    if (!step) continue;
    step.updateMatrixWorld(true);
    const box = new THREE.Box3().setFromObject(step);
    heights[name] = box.max.y - box.min.y;
  }
  return heights;
}

